// Detects team styles at user level. No side effects on import (only node:fs, node:os, node:path and
// sync-rules.mjs, which imports nothing), so that sync.mjs can load it before team/roles.json or team.config.json exist.

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { LEGACY_MARKERS, MARKER } from "../sync-rules.mjs";

// Start of every marker line, old (German, before 0.4.0) and new: "generated by team/sync.mjs" etc.
const MARKER_STARTS = [MARKER, ...LEGACY_MARKERS].map((m) => m.split(" – ")[0]);

// Team styles at user level: files in <home>/.claude/output-styles/ with the generator marker.
// They act in every project and override the project styles there. Only reads, deletes nothing.
export function userLevelTeamStyles() {
    const dir = path.resolve(os.homedir(), ".claude", "output-styles");
    let names;
    try {
        names = fs.readdirSync(dir);
    } catch {
        return [];
    }
    const found = [];
    for (const name of names.sort()) {
        const file = path.join(dir, name);
        try {
            if (!fs.statSync(file).isFile()) continue;
            const text = fs.readFileSync(file, "utf8");
            if (MARKER_STARTS.some((m) => text.includes(m))) found.push(file);
        } catch {}
    }
    return found;
}

// Warning for stderr, or null when nothing was found.
export function userLevelTeamStylesWarning() {
    const files = userLevelTeamStyles();
    if (!files.length) return null;
    return (
        "Warning: team styles found at user level. They act in other projects and override their styles there.\n" +
        files.map((f) => `  ${f}`).join("\n") +
        "\nPlease remove these files (global configuration, not touched here).\n"
    );
}
